import JSZip from 'jszip';
import './style.css';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='soundlab.settings.v1', JOURNAL='soundlab.journal.v1';
const settings=JSON.parse(localStorage.getItem(KEY)||'{}');
const journal=JSON.parse(localStorage.getItem(JOURNAL)||'[]');
let token=null, expires=0, me=null, playlists=[], selected=null, tracks=[], duplicateGroups=[], plays=[], current='dashboard', toastTimer;
let scanProgress=null, historyPeriod='all', historyAnchor='', historyFrom='', historyTo='', historyArtwork=new Map(), artworkLoading=false, artworkError='', artworkLastQuery='', artworkTimer=null;
const ARTWORK_KEY='soundlab.artwork.v1';
const TIMEZONES=['Australia/Brisbane','Australia/Sydney','Australia/Melbourne','Australia/Adelaide','Australia/Perth','Australia/Darwin','Australia/Hobart','Pacific/Auckland','Europe/London','Europe/Berlin','America/New_York','America/Chicago','America/Denver','America/Los_Angeles','Asia/Tokyo','Asia/Singapore','UTC'];
function timezone(){const z=settings.timezone||'Australia/Brisbane';try{new Intl.DateTimeFormat('en-AU',{timeZone:z}).format(new Date());return z}catch{return 'Australia/Brisbane'}}
const formatterCache=new Map();
function partsFor(ts){const z=timezone();let fmt=formatterCache.get(z);if(!fmt){fmt=new Intl.DateTimeFormat('en-GB',{timeZone:z,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23',minute:'2-digit'});formatterCache.set(z,fmt)}const o={};for(const part of fmt.formatToParts(new Date(ts)))if(part.type!=='literal')o[part.type]=part.value;return {day:`${o.year}-${o.month}-${o.day}`,year:o.year,month:`${o.year}-${o.month}`,hour:o.hour}}
function localToday(){return partsFor(Date.now()).day}
historyAnchor=localToday();
try{const cache=JSON.parse(localStorage.getItem(ARTWORK_KEY)||'[]');if(Array.isArray(cache))for(const [k,v] of cache.slice(0,100))if(typeof k==='string'&&v&&typeof v.image==='string')historyArtwork.set(k,v)}catch{}
function saveArtwork(){try{localStorage.setItem(ARTWORK_KEY,JSON.stringify([...historyArtwork].slice(-100)))}catch{}}
function artworkSignature(){if(!me||!plays.length)return '';const r=topFromData(filteredPlays());return JSON.stringify([...r.artists.slice(0,8).map(([a])=>['artist',a,'']),...r.albums.filter(a=>a.name!=='Unknown album').slice(0,8).map(a=>['album',a.artist,a.name]),...r.songs.slice(0,8).map(a=>['song',a.artist,a.name])])}
function scheduleArtwork(){if(current!=='history'||!me||!plays.length||artworkLoading)return;clearTimeout(artworkTimer);artworkTimer=setTimeout(()=>{const signature=artworkSignature();if(signature!==artworkLastQuery){artworkLastQuery=signature;loadAnalyticsArtwork().catch(err=>{artworkError=String(err.message||err);render()})}},200)}
const saveSettings=()=>localStorage.setItem(KEY,JSON.stringify(settings));
function elIcon(n){let paths={home:'⌂',playlist:'♫',history:'◷',journal:'◎',tools:'✦',vault:'▣',settings:'⚙',discover:'◇'};return paths[n]||'•'}
const menu=[['dashboard','Dashboard','home'],['playlists','Playlist Studio','playlist'],['history','Listening Analytics','history'],['journal','Album Journal','journal'],['tools','Playlist Paster','tools'],['vault','Music Vault','vault'],['discover','Power Tools','discover'],['settings','Settings & Data','settings']];
const btn=(label,id,cls='secondary')=>`<button class="button ${cls}" data-action="${id}">${label}</button>`;
function toast(msg,error=false){let node=$('#toast');if(!node)return;node.textContent=msg;node.style.color=error?'#ffbaba':'#90f0ad';node.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.style.display='none',6500)}
function title(name,desc){return `<div class="eyebrow">YOUR MUSIC, YOUR RULES</div><h1 class="heading">${name}</h1><p class="muted lead">${desc}</p>`}
function shell(){return `<div class="shell"><aside class="sidebar"><div><div class="logo">Sound<b>Lab.</b></div><div class="tagline">A whole new way to manage music</div></div><div class="nav">${menu.map(([id,n,icon])=>`<button data-page="${id}" class="${id===current?'active':''}"><span>${elIcon(icon)}</span><span class="label">${n}</span></button>`).join('')}</div><div class="sidebarFoot">Independent music toolkit.<br>Not affiliated with Spotify.<br>v0.8 · visual analytics</div></aside><main class="main"><div class="top"><span class="chip">${me?'● Connected as '+esc(me.display_name||me.id):'○ Not connected'}</span><span class="row">${me?btn('Refresh playlists','refresh','ghost'):btn('Connect Spotify','connect','secondary')}</span></div><div id="content">${page()}</div><div id="toast" style="display:none;margin-top:18px" role="status"></div><div class="footer">SoundLab is independent from Playlist Paster. Your imported listening history remains in this browser, unless you export it yourself.</div></main></div><nav class="mobileNav">${menu.filter(x=>['dashboard','playlists','history','journal','settings'].includes(x[0])).map(([id,n,i])=>`<button data-page="${id}" class="${id===current?'active':''}"><span>${elIcon(i)}</span>${n.split(' ')[0]}</button>`).join('')}</nav>`}
function render(){document.querySelector('#app').innerHTML=shell();scheduleArtwork()}
function page(){switch(current){case'dashboard':return dashboard();case'playlists':return playlistsPage();case'history':return historyPage();case'journal':return journalPage();case'tools':return pasterPage();case'vault':return vaultPage();case'discover':return discoverPage();case'settings':return settingsPage();}}
function dashboard(){return `${title('Your music command centre','Organise your playlists, keep your music journal and explore the history you choose to import.')}<div class="layout"><section class="panel hero span8"><div class="eyebrow">WELCOME TO SOUNDLAB</div><h2 style="font:800 28px Manrope;margin-bottom:8px">Music management without the mess.</h2><p class="lead">A brand-new standalone website. Connect Spotify to manage playlists, or explore your own listening export offline.</p><div class="row">${btn(me?'Open Playlist Studio':'Connect Spotify',me?'goto-playlists':'connect','primary')}${btn('Import my history','goto-history','ghost')}</div></section><section class="panel span4"><h3>Your setup</h3><div class="stack"><span>${me?'✅ Spotify account connected':'○ Spotify account not connected'}</span><span>${plays.length?'✅ '+plays.length.toLocaleString()+' imported plays':'○ No historical data imported yet'}</span><span>🔒 Imports saved in this browser</span><span>◷ Listening statistics use only your imported history files.</span></div></section><section class="panel span4"><div class="muted small">Playlists loaded</div><div class="stat">${playlists.length}</div><p class="muted small">Owned and followed Spotify playlists</p></section><section class="panel span4"><div class="muted small">Imported streams</div><div class="stat">${plays.length.toLocaleString()}</div><p class="muted small">From user-supplied exports only</p></section><section class="panel span4"><div class="muted small">Albums in journal</div><div class="stat">${journal.length}</div><p class="muted small">Your private album diary</p></section><section class="panel span12"><h3>Choose how you start</h3><div class="row"><button class="choice ${settings.onboarding!=='import'?'selected':''}" data-action="choose-now"><h3>▶ Start now</h3><p>Use the website immediately. No export required. You can import your listening history whenever you want.</p></button><button class="choice ${settings.onboarding==='import'?'selected':''}" data-action="choose-import"><h3>↓ Bring my history</h3><p>Request Extended Streaming History from Spotify; it may take weeks. Import it when it arrives.</p></button></div><p class="muted small">Listening history is not automatically collected. Spotify API data cannot be used to generate the listening statistics we planned under current developer policy. Import a new Spotify history export whenever you want to update your charts. Playlist refresh still works on demand.</p></section></div>`}
function playlistsPage(){return `${title('Playlist Studio','Inspect your Spotify playlists, identify exact duplicates and remove extra occurrences directly from the selected playlist.')}<div class="layout"><section class="panel span4"><div class="row spread"><h3>Your playlists</h3>${btn('↻','refresh','ghost')}</div><input id="playlistSearch" class="input" placeholder="Search playlists" autocomplete="off"><div id="playlistList" class="list" style="margin-top:14px;max-height:570px;overflow:auto">${playlistCards()}</div></section><section class="panel span8"><div id="playlistDetail">${playlistDetail()}</div></section></div>`}
function playlistCards(filter=''){let list=playlists.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase()));return list.length?list.map(p=>`<button class="item" data-playlist="${esc(p.id)}" style="text-align:left;color:inherit;width:100%;cursor:pointer"><span class="row" style="flex-wrap:nowrap"><span class="cover placeholder">♫</span><span><span class="itemTitle">${esc(p.name)}</span><div class="itemSub">${p.items?.total??p.tracks?.total??'?'} items · ${p.owner?.id===me?.id?'Owned':'Followed'}</div></span></span><span>›</span></button>`).join(''):`<div class="empty">${me?'No matching playlists':'Connect Spotify to load your playlists.'}</div>`}
function playlistDetail(){if(!selected)return '<div class="empty"><h3>Select a playlist</h3><p>Choose a playlist from the left to inspect and clean it.</p></div>';const own=selected.owner?.id===me?.id;const grouped=duplicateGroups;if(scanProgress?.active)return `<div class="row spread"><h3>${esc(selected.name)}</h3><span class="chip">Scanning playlist</span></div><p class="muted small" id="scanProgressText" role="status" aria-live="polite">${scanProgress.loaded.toLocaleString()} of ${scanProgress.total?scanProgress.total.toLocaleString():'…'} tracks checked</p><div class="scanTrack" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${scanProgress.percent}" id="scanProgressBar"><div id="scanProgressFill" style="width:${scanProgress.percent}%"></div></div><p class="muted small">Checking each page of songs for exact Spotify URI duplicates. Please keep this tab open.</p>`;return `<div class="row spread"><div><h3>${esc(selected.name)}</h3><p class="muted small">${tracks.length} items · ${own?'Owned by you':'Read-only followed playlist'}</p></div><a href="${esc(selected.external_urls?.spotify||'https://open.spotify.com')}" target="_blank" rel="noopener">Open in Spotify ↗</a></div><div class="note">Duplicate Detective matches identical Spotify URIs. Different recordings or remasters are not automatically treated as duplicates. Removing duplicates edits <strong>this playlist directly</strong>. It retains one copy of each track in the original order. Because Spotify removes all occurrences of a URI, SoundLab removes those copies and reinserts one; this resets the retained track’s Date Added. A local backup is saved before editing.</div><div class="divider"></div><h3>Duplicate scan</h3>${grouped.length?`<p class="success">${grouped.reduce((n,g)=>n+g.count-1,0)} extra occurrences across ${grouped.length} tracks</p><div class="list">${grouped.slice(0,30).map(g=>`<div class="item"><div><div class="itemTitle">${esc(g.name)}</div><div class="itemSub">${esc(g.artist)}</div></div><span class="chip">${g.count} copies</span></div>`).join('')}</div>${grouped.length>30?'<p class="muted">Showing the first 30 groups.</p>':''}${own?`<div class="divider"></div>${btn('Remove duplicates from this playlist','clean','primary')}`:'<p class="muted">Only playlists you own can be copied or edited here.</p>'}`:`<p class="muted">No exact URI duplicates detected in this playlist.</p>`}<div class="divider"></div><div class="row spread"><h3>Tracks</h3>${btn('Save local backup','backup','ghost')}</div><div class="list">${tracks.slice(0,75).map((it,i)=>{let t=it.item||it.track||{};return `<div class="item"><div><div class="itemTitle">${i+1}. ${esc(t.name||'Unavailable item')}</div><div class="itemSub">${esc((t.artists||[]).map(a=>a.name).join(', ')||'Unknown artist')}</div></div></div>`}).join('')}</div>${tracks.length>75?'<p class="muted small">Showing first 75 tracks.</p>':''}</div>`}
const normTrack=(it)=>it.item||it.track||{};
function scan(items){let map=new Map();items.forEach((it,i)=>{let t=normTrack(it);if(!t.uri)return;let m=map.get(t.uri)||{uri:t.uri,name:t.name,artist:(t.artists||[]).map(a=>a.name).join(', '),count:0};m.count++;map.set(t.uri,m)});return [...map.values()].filter(x=>x.count>1)}
function historyBounds(){
 // Date comparisons use the calendar date in the selected IANA time zone.
 // Spotify timestamps remain stored in UTC, unchanged.
 if(historyPeriod==='all')return [null,null];
 if(historyPeriod==='custom')return [historyFrom||null,historyTo||null];
 const date=/^\d{4}-\d{2}-\d{2}$/.test(historyAnchor)?historyAnchor:localToday();
 const [year,month,day]=date.split('-').map(Number);
 const utc=new Date(Date.UTC(year,month-1,day));
 const fmt=d=>d.toISOString().slice(0,10);
 if(historyPeriod==='day')return [date,date];
 if(historyPeriod==='week'){const monday=(utc.getUTCDay()+6)%7;return [fmt(new Date(utc.getTime()-monday*86400000)),fmt(new Date(utc.getTime()+(6-monday)*86400000))]}
 if(historyPeriod==='month')return [`${year}-${String(month).padStart(2,'0')}-01`,fmt(new Date(Date.UTC(year,month,0)))];
 if(historyPeriod==='year')return [`${year}-01-01`,`${year}-12-31`];
 return [null,null];
}
function filteredPlays(){const [from,to]=historyBounds();return plays.filter(p=>{let day=partsFor(p.ts).day;return (!from||day>=from)&&(!to||day<=to)})}
function topFromData(data){let artist=new Map(),songs=new Map(),albums=new Map();for(const p of data){let a=p.artist||'Unknown',name=p.track||'Unknown',album=p.album||'Unknown album';artist.set(a,(artist.get(a)||0)+p.ms);let sk=a+'\u0000'+name,s=songs.get(sk)||{artist:a,name,ms:0,plays:0};s.ms+=p.ms;s.plays++;songs.set(sk,s);let ak=a+'\u0000'+album,al=albums.get(ak)||{artist:a,name:album,ms:0,plays:0};al.ms+=p.ms;al.plays++;albums.set(ak,al)}return {artists:[...artist].sort((a,b)=>b[1]-a[1]),songs:[...songs.values()].sort((a,b)=>b.plays-a.plays),albums:[...albums.values()].sort((a,b)=>b.ms-a.ms)}}
const artKey=(type,artist,name='')=>type+'|'+artist.toLowerCase().trim()+'|'+name.toLowerCase().trim();
function pictureFor(type,artist,name=''){
 const art=historyArtwork.get(artKey(type,artist,name));
 return art?.image?`<a href="${esc(art.url||'https://open.spotify.com')}" target="_blank" rel="noopener" aria-label="Open on Spotify"><img class="analyticsArtwork" src="${esc(art.image)}" loading="lazy" alt="${esc(type==='artist'?'Artist photo':'Album cover')}" referrerpolicy="no-referrer"></a>`:`<div class="analyticsArtwork placeholder">${type==='artist'?'♫':'▣'}</div>`;
}
function visualRanks(rows,type){if(!rows.length)return '<p class="muted">No plays in this period.</p>';
 return `<div class="visualRanks">${rows.map((row,i)=>{const artist=type==='artist'?row[0]:row.artist;const name=type==='artist'?row[0]:row.name;const value=type==='artist'?row[1]:type==='song'?row.plays:row.ms;return `<div class="visualRank"><span class="rankNumber">${i+1}</span>${pictureFor(type,artist,type==='artist'?'':name)}<div class="rankDetails"><strong title="${esc(name)}">${esc(name)}</strong>${type==='artist'?'<small>Artist</small>':`<small>${esc(artist)}</small>`}</div><span class="rankAmount">${type==='song'?value.toLocaleString()+' plays':(value/3600000).toFixed(1)+'h'}</span></div>`}).join('')}</div>`}
function simpleBars(rows,fmt){let max=Math.max(1,...rows.map(r=>r[1]));return rows.length?rows.map(([label,n])=>`<div class="barRow"><span title="${esc(label)}">${esc(label)}</span><div class="bar"><div style="width:${Math.max(2,n/max*100)}%"></div></div><strong>${esc(fmt(n))}</strong></div>`).join(''):'<p class="muted">No activity for these dates.</p>'}
function historyPage(){
 const data=filteredPlays(),total=data.reduce((a,p)=>a+p.ms,0),rank=topFromData(data),dates=plays.map(p=>p.ts).sort(),fullRange=dates.length?`${partsFor(dates[0]).day} → ${partsFor(dates.at(-1)).day}`:'No history yet';
 const byDay=new Map(),byHour=new Map(),byYear=new Map();
 for(const p of data){let local=partsFor(p.ts),day=local.day,hour=local.hour+':00',year=local.year;byDay.set(day,(byDay.get(day)||0)+p.ms);byHour.set(hour,(byHour.get(hour)||0)+p.ms);byYear.set(year,(byYear.get(year)||0)+p.ms)}
 let grouped=historyPeriod==='year'?[...new Map([...byDay].map(([d])=>[d.slice(0,7),0]))].map(([m])=>[m,[...byDay].filter(([d])=>d.startsWith(m)).reduce((n,x)=>n+x[1],0)]):historyPeriod==='all'?[...byYear]:[...byDay].sort((a,b)=>a[0].localeCompare(b[0])).slice(-31);
 const all=plays.length,unknown=all-data.length;
 return `${title('Listening Analytics','Your music in pictures, with time-period filters and a shareable recap. Based on your own uploaded streaming history.')}
 <div class="note">Your listening-history import stays in this browser. These charts only reflect imported records, not live Spotify plays. Spotify's developer policy restricts generating listening metrics from API data, so SoundLab does not offer automatic stream syncing. Artist photos and album covers load automatically when Spotify is connected (where available); images are not used to count streams. <a href="https://www.spotify.com/account/privacy/" target="_blank" rel="noopener">Request your Spotify export ↗</a></div>
 <section class="panel" style="margin-top:16px"><div class="row spread"><div><h3>Explore a period</h3><p class="muted small">Dates and hours are displayed in ${esc(timezone())}. Spotify's original UTC timestamps are preserved.</p></div><div class="row">${btn('Download recap PNG','export-recap','primary')}<span class="chip">${artworkLoading?'Loading artwork…':!me?'Connect Spotify for artwork':artworkError?'Artwork temporarily unavailable':'Artwork loads automatically'}</span></div></div>
 <div class="row" style="margin:12px 0"><label class="field" style="min-width:240px">Display timezone<select class="select" id="historyTimezone">${timezoneOptions()}</select></label></div><div class="periodTabs">${[['all','All time'],['day','Day'],['week','Week'],['month','Month'],['year','Year'],['custom','Custom']].map(([id,name])=>`<button class="${historyPeriod===id?'selected':''}" data-period="${id}">${name}</button>`).join('')}</div>
 ${historyPeriod==='custom'?`<div class="row" style="margin-top:12px"><label class="field">From<input class="input" type="date" id="historyFrom" value="${esc(historyFrom)}"></label><label class="field">To<input class="input" type="date" id="historyTo" value="${esc(historyTo)}"></label></div>`:historyPeriod!=='all'?`<label class="field" style="max-width:235px;margin-top:12px">Select date<input class="input" type="date" id="historyAnchor" value="${esc(historyAnchor)}"></label>`:''}
 </section>
 <div class="layout" style="margin-top:16px"><section class="panel span4"><div class="muted small">Plays in selected period</div><div class="stat">${data.length.toLocaleString()}</div><div class="muted small">${unknown.toLocaleString()} other records outside filter</div></section><section class="panel span4"><div class="muted small">Listening time</div><div class="stat">${(total/3600000).toFixed(1)}h</div></section><section class="panel span4"><div class="muted small">Imported history coverage</div><div style="font-weight:700;margin-top:10px">${esc(fullRange)}</div></section>
 <section class="panel span6"><h3>Top artists</h3>${visualRanks(rank.artists.slice(0,10),'artist')}</section>
 <section class="panel span6"><h3>Top tracks</h3>${visualRanks(rank.songs.slice(0,10),'song')}</section>
 <section class="panel span6"><h3>Top albums</h3>${visualRanks(rank.albums.filter(a=>a.name!=='Unknown album').slice(0,10),'album')}</section>
 <section class="panel span6"><h3>Listening over time</h3>${simpleBars(grouped.slice(-15),v=>(v/3600000).toFixed(1)+'h')}</section>
 <section class="panel span12"><h3>Time of day · ${esc(timezone())}</h3><div class="hoursGrid">${Array.from({length:24},(_,h)=>{let n=byHour.get(String(h).padStart(2,'0')+':00')||0;let max=Math.max(1,...byHour.values());return `<div class="hourTile" title="${h}:00 ${esc(timezone())} · ${(n/3600000).toFixed(1)} hours" style="background:rgba(75,224,131,${(.08+.85*n/max).toFixed(2)})"><strong>${String(h).padStart(2,'0')}</strong></div>`}).join('')}</div><p class="muted small">Hours reflect your selected timezone. Change it in Settings & Data.</p></section>
 <section class="panel span12"><h3>Forgotten favourites</h3><p class="muted small">Tracks with 10+ plays in your full imported history and no plays during its last 180 days. Calculated relative to your latest imported record.</p>${(()=>{let latest=dates.length?Date.parse(dates.at(-1)):0,m=new Map();for(let p of plays){let k=p.track+' — '+p.artist,x=m.get(k)||{n:0,last:0};x.n++;x.last=Math.max(x.last,Date.parse(p.ts));m.set(k,x)}return [...m].filter(([,x])=>x.n>=10&&latest-x.last>180*86400000).sort((a,b)=>b[1].n-a[1].n).slice(0,12).map(([k,x])=>`<div class="item"><strong>${esc(k)}</strong><span class="muted small">${x.n} plays · last ${partsFor(x.last).day}</span></div>`).join('')||'<p class="muted">No matches yet.</p>'})()}</section>
 <section class="panel span12"><h3>Import more Spotify history</h3><p class="muted small">Upload ZIP or JSON exports anytime. Identical imported record fingerprints are deduplicated. Later exports add newer or older history; SoundLab does not track new plays automatically under Spotify's developer policy.</p><input type="file" id="historyFiles" accept=".zip,.json,application/json,application/zip" multiple class="input"><div class="row" style="margin-top:13px">${btn('Import files','import-history','primary')}${btn('Export my records','export-history','ghost')}</div><div id="importStatus" class="muted small" style="margin-top:10px"></div></section></div>`;
}
async function loadAnalyticsArtwork(){
 if(!me)throw Error('Connect Spotify first to load official artist and album images. Your imported history is still available offline.');
 if(artworkLoading)return;
 artworkLoading=true;const button=document.querySelector('[data-action="load-artwork"]');if(button)button.textContent='Loading artwork…';
 artworkError='';const top=topFromData(filteredPlays()),targets=[...top.artists.slice(0,8).map(([a])=>['artist',a,'']),...top.albums.slice(0,8).filter(a=>a.name!=='Unknown album').map(a=>['album',a.artist,a.name]),...top.songs.slice(0,8).map(a=>['song',a.artist,a.name])];
 let loaded=0;
 try{for(const [type,artist,name] of targets){const key=artKey(type,artist,name);if(historyArtwork.has(key))continue;
  try{const query=type==='artist'?`artist:${artist}`:type==='album'?`album:${name} artist:${artist}`:`track:${name} artist:${artist}`;
   const json=await api('/search?'+new URLSearchParams({q:query,type:type==='song'?'track':type,limit:'3'}));
   const found=(type==='artist'?json.artists?.items:type==='album'?json.albums?.items:json.tracks?.items)||[];
   const lower=x=>String(x||'').toLowerCase().trim();
   const match=found.find(x=>lower(x.name)===lower(type==='artist'?artist:name));
   if(match){const item=type==='song'?match.album:match;historyArtwork.set(key,{image:item?.images?.[0]?.url||'',url:match.external_urls?.spotify||item?.external_urls?.spotify||''});loaded++}else historyArtwork.set(key,{image:'',url:''});
  }catch(err){if(String(err.message).includes('429')||String(err.message).includes('401')||String(err.message).includes('403'))throw err;historyArtwork.set(key,{image:'',url:''})}
 }
 }finally{artworkLoading=false;saveArtwork();render();if(loaded)toast(`Loaded artwork for ${loaded} entries.`)}
}
function exportRecap(){
 const data=filteredPlays();if(!data.length)throw Error('No imported history for this date selection.');
 const top=topFromData(data),w=1080,h=1350,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');
 const bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#0c1912');bg.addColorStop(.55,'#173d29');bg.addColorStop(1,'#070f0a');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
 ctx.fillStyle='#4ce28a';ctx.font='bold 28px Arial';ctx.fillText('SOUNDLAB  /  MY MUSIC RECAP',74,105);
 ctx.fillStyle='#f5fff7';ctx.font='bold 66px Arial';ctx.fillText(historyPeriod==='all'?'All-time listening':historyPeriod==='custom'?'Custom listening recap':historyPeriod[0].toUpperCase()+historyPeriod.slice(1)+' listening recap',74,202);
 ctx.fillStyle='#b9dac6';ctx.font='26px Arial';let [from,to]=historyBounds();ctx.fillText(from&&to?`${from}  –  ${to} · ${timezone()}`:'Your imported Spotify streaming history · '+timezone(),74,254);
 ctx.fillStyle='#214c32';ctx.fillRect(65,300,950,155);ctx.fillStyle='#f6fff8';ctx.font='bold 49px Arial';ctx.fillText(data.length.toLocaleString(),94,375);ctx.fillText((data.reduce((n,p)=>n+p.ms,0)/3600000).toFixed(1)+'h',585,375);ctx.font='25px Arial';ctx.fillStyle='#a8d7b8';ctx.fillText('PLAY RECORDS',95,416);ctx.fillText('LISTENING TIME',586,416);
 let y=525;const section=(label,rows,format)=>{ctx.fillStyle='#57e18e';ctx.font='bold 28px Arial';ctx.fillText(label,80,y);y+=53;rows.forEach((r,i)=>{ctx.fillStyle='#f6fff8';ctx.font='24px Arial';const str=(i+1)+'. '+r[0];let txt=str;while(ctx.measureText(txt).width>710)txt=txt.slice(0,-2)+'…';ctx.fillText(txt,85,y);ctx.fillStyle='#b5dec1';ctx.font='22px Arial';ctx.textAlign='right';ctx.fillText(format(r[1]),990,y);ctx.textAlign='left';y+=57});y+=42};
 section('TOP ARTISTS',top.artists.slice(0,5),v=>(v/3600000).toFixed(1)+'h');
 section('TOP SONGS',top.songs.slice(0,5).map(x=>[x.name+' — '+x.artist,x.plays]),v=>v+' plays');
 ctx.fillStyle='#97bca5';ctx.font='20px Arial';ctx.fillText('Based on user-imported history • Created with SoundLab',80,1310);
 canvas.toBlob(blob=>{if(!blob){toast('Could not generate PNG.',true);return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='soundlab-music-recap.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)},'image/png');
}
function rankBars(list,fmt){let max=Math.max(...list.map(x=>x[1]),1);return list.map(([name,n])=>`<div class="barRow"><span title="${esc(name)}">${esc(name)}</span><div class="bar"><div style="width:${Math.max(2,100*n/max)}%"></div></div><strong>${esc(fmt(n))}</strong></div>`).join('')}
function journalPage(){return `${title('Album Journal','Search Spotify albums to autofill the details, then rate and review. You can still add albums manually.')}<div class="layout"><section class="panel span4"><h3>Add or review an album</h3><div class="stack" style="margin-bottom:16px"><label class="field">Search Spotify albums<input class="input" id="albumSearch" placeholder="e.g. Hysteria Def Leppard" autocomplete="off"></label><div class="row">${btn('Find albums','search-albums','secondary')}</div><div id="albumResults" class="albumResults" role="status"><p class="muted small">${me?'Search for an album, then select a result to fill in the details.':'Connect Spotify to search albums, or enter the details manually below.'}</p></div></div><form id="albumForm" class="stack"><input type="hidden" name="spotifyId"><input type="hidden" name="spotifyUrl"><input type="hidden" name="image"><input type="hidden" name="releaseDate"><input type="hidden" name="totalTracks"><div id="albumSelected" class="albumSelection hidden"></div><label class="field">Album title<input class="input" name="name" required maxlength="180"></label><label class="field">Artist<input class="input" name="artist" required maxlength="180"></label><label class="field">Rating<select class="select" name="rating"><option value="">Not rated yet</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label><label class="field">Status<select class="select" name="status"><option>Want to listen</option><option>Listening</option><option>Finished</option></select></label><label class="field">Your review / notes<textarea class="textarea" name="notes" maxlength="3000" placeholder="Favourite tracks, what you loved, what you didn't..."></textarea></label><button class="button" type="submit">Save to my album journal</button></form></section><section class="panel span8"><h3>My albums (${journal.length})</h3><div class="list">${journal.length?journal.map((j,i)=>`<div class="item albumEntry"><div class="row" style="flex-wrap:nowrap;min-width:0"><span class="albumThumb">${j.image?`<img src="${esc(j.image)}" alt="${esc(j.name)} album cover" loading="lazy">`:'♫'}</span><div style="min-width:0"><div class="itemTitle">${esc(j.name)} · ${esc(j.artist)}</div><div class="itemSub">${j.releaseDate?esc(j.releaseDate.slice(0,4))+' · ':''}${esc(j.status)} · ${j.rating?j.rating+'/5 stars':'Unrated'}</div>${j.notes?`<p class="muted small journalNotes">${esc(j.notes)}</p>`:''}${j.spotifyUrl?`<a href="${esc(j.spotifyUrl)}" target="_blank" rel="noopener noreferrer" class="small">View album on Spotify ↗</a>`:''}</div></div><button class="button ghost" data-delete-album="${i}">Remove</button></div>`).join(''):'<div class="empty">Your album journal is empty. Search Spotify or enter your first album manually!</div>'}</div></section></div>`}
let albumSearchResults=[];
async function searchAlbums(){const input=$('#albumSearch'),result=$('#albumResults');if(!input||!result)return;const q=input.value.trim();if(q.length<2)throw Error('Enter at least two characters to search albums.');result.innerHTML='<p class="muted small">Searching Spotify…</p>';try{const data=await api('/search?'+new URLSearchParams({q,type:'album',limit:'10'}));albumSearchResults=(data.albums?.items||[]).filter(a=>a&&a.id);result.innerHTML=albumSearchResults.length?albumSearchResults.map((a,i)=>`<button type="button" class="albumResult" data-pick-album="${i}"><span class="albumThumb">${a.images?.[0]?.url?`<img src="${esc(a.images[0].url)}" alt="" loading="lazy">`:'♫'}</span><span class="albumResultInfo"><strong>${esc(a.name)}</strong><span class="muted small">${esc((a.artists||[]).map(x=>x.name).join(', '))} · ${esc(a.release_date?.slice(0,4)||'Year unknown')} · ${esc(a.album_type||'Album')}</span></span><span aria-hidden="true">＋</span></button>`).join(''):'<p class="muted small">No albums found. Try adding the artist name, or enter the album manually.</p>'}catch(e){result.innerHTML='<p class="error small">'+esc(e.message)+'</p>';throw e}}
function pickAlbum(index){const a=albumSearchResults[index],form=$('#albumForm');if(!a||!form)return;const vals={name:a.name,artist:(a.artists||[]).map(x=>x.name).join(', '),spotifyId:a.id,spotifyUrl:a.external_urls?.spotify||'',image:a.images?.[0]?.url||'',releaseDate:a.release_date||'',totalTracks:String(a.total_tracks||'')};for(const [key,value] of Object.entries(vals)){const field=form.elements.namedItem(key);if(field)field.value=value}const selected=$('#albumSelected');selected.classList.remove('hidden');selected.innerHTML=`<div class="row" style="flex-wrap:nowrap"><span class="albumThumb">${vals.image?`<img src="${esc(vals.image)}" alt="" loading="lazy">`:'♫'}</span><span><strong>${esc(vals.name)}</strong><br><span class="muted small">${esc(vals.artist)} · ${esc(vals.releaseDate||'Release unknown')}${vals.totalTracks?' · '+esc(vals.totalTracks)+' tracks':''}</span></span></div><div class="row" style="margin-top:9px"><a class="small" href="${esc(vals.spotifyUrl)}" rel="noopener noreferrer" target="_blank">View on Spotify ↗</a>${btn('Clear selection','clear-album','ghost')}</div>`;$('#albumResults').innerHTML='<p class="success small">Album selected! Now add your rating and review below.</p>';toast('Album details filled in. Add a review and save!')}
function clearAlbumSelection(){const form=$('#albumForm');if(!form)return;for(const key of ['spotifyId','spotifyUrl','image','releaseDate','totalTracks'])form.elements.namedItem(key).value='';$('#albumSelected').classList.add('hidden');$('#albumSelected').innerHTML=''}

function pasterPage(){return `${title('Playlist Paster tool','A new built-in song-list importer for SoundLab. The original Playlist Paster remains a completely separate website.')}<div class="layout"><section class="panel span6"><h3>Paste a song list</h3><p class="muted small">One song per line, in Song - Artist format. SoundLab searches Spotify and previews matches before creating a playlist.</p><label class="field">New playlist name<input id="pasteName" class="input" value="My SoundLab Mix"></label><label class="field" style="margin-top:12px">Tracks<textarea id="pasteText" class="textarea" placeholder="Romeo and Juliet - Dire Straits&#10;Hysteria - Def Leppard"></textarea></label><div class="row" style="margin-top:14px">${btn('Find tracks','find-pasted','primary')}</div></section><section class="panel span6"><h3>Search results</h3><div id="pasteResults" class="muted">Paste songs and select Find tracks. Exact matches should be checked before creating the playlist.</div></section></div>`}
function vaultPage(){let backups=JSON.parse(localStorage.getItem('soundlab.backups.v1')||'[]');return `${title('Music Vault','Download and restore your own playlist backups, with a confirmation before modifying Spotify.')}<div class="note">Restoring replaces the playlist's current song list. SoundLab verifies the playlist has not changed since you opened it, then asks you to confirm. Backups live in this browser until you export them.</div><div class="layout" style="margin-top:16px"><section class="panel span12"><div class="row spread"><h3>Saved backups (${backups.length})</h3>${btn('Export album journal','export-journal','ghost')}</div><div class="list">${backups.length?backups.map((b,i)=>`<div class="item"><div><div class="itemTitle">${esc(b.name)}</div><div class="itemSub">${b.uris.length} items · ${esc(b.date)}</div></div><div class="row">${btn('Download','download-backup-'+i,'ghost')}${btn('Restore','restore-backup-'+i,'secondary')}</div></div>`).join(''):'<div class="empty">Open a playlist and choose Save local backup.</div>'}</div></section><section class="panel span12"><h3>Import an existing backup</h3><input type="file" id="backupFile" class="input" accept=".json,application/json"><div class="row" style="margin-top:10px">${btn('Add backup to vault','import-backup','secondary')}</div></section></div>`}
const upcoming={'Discography Detective':'Complete-catalogue comparison requires available catalogue information or a user-provided track list.','Playlist Architect':'The chapter planner below stores your own playlist narrative locally.','Smart artist version matching':'Album/single/remaster similarity needs user confirmation before deleting.','Listening history updates':'Import a newer Spotify Extended Streaming History export whenever you want to update statistics. Automatic background stream tracking is not offered because the planned analytics use is restricted by Spotify developer policy.'};
function discoverPage(){let plan=JSON.parse(localStorage.getItem('soundlab.architect.v1')||'[]');return `${title('Power Tools','Compare, merge, sort, search and creatively plan playlists. Changes are always previewed and confirmed.')}<div class="layout"><section class="panel span6"><h3>Playlist DNA · Compare</h3><p class="muted small">Select two playlists you own or can access. SoundLab checks which exact tracks overlap.</p>${playlistPicker('compareA')}${playlistPicker('compareB')}${btn('Compare playlists','compare','primary')}<div id="compareResult"></div></section><section class="panel span6"><h3>Playlist mixer · Merge</h3><p class="muted small">Create a NEW playlist by combining two existing ones, optionally keeping just one copy of each URI.</p>${playlistPicker('mergeA')}${playlistPicker('mergeB')}<label class="field">New playlist name<input id="mergeName" class="input" placeholder="My combined mix"></label><label class="field"><input type="checkbox" id="mergeUnique" checked> Exclude exact duplicates</label>${btn('Preview merge','preview-merge','secondary')}<div id="mergeResult"></div></section><section class="panel span6"><h3>Playlist sorter</h3><p class="muted small">Reorder a playlist you own by track or artist name. SoundLab backs up the original order.</p>${playlistPicker('sortPlaylist')}<select id="sortMode" class="select"><option value="title">Track title A–Z</option><option value="artist">Artist A–Z</option><option value="album">Album A–Z</option><option value="reverse">Reverse track order</option></select><div class="row">${btn('Preview sort','preview-sort','secondary')}</div><div id="sortResult"></div></section><section class="panel span6"><h3>Cross-playlist song finder</h3><p class="muted small">Search playlists for a song or artist. To respect API rate limits, scans your accessible playlists on demand.</p><input id="globalSearch" class="input" placeholder="Song or artist"><div class="row">${btn('Search playlists','global-search','secondary')}</div><div id="globalResult"></div></section><section class="panel span12"><h3>Playlist Architect · Story chapters</h3><p class="muted small">Draft a narrative with song titles and chapters, saved locally as text. No Spotify playlist changes are made.</p><form id="architectForm" class="row"><input name="name" class="input" required maxlength="100" placeholder="Story title"><textarea name="chapters" class="textarea" required placeholder="Act I: Meeting\nSong - Artist\nAct II: Longing\nSong - Artist"></textarea><button class="button primary" type="submit">Save story</button></form><div class="list">${plan.map((x,i)=>`<div class="item"><div><strong>${esc(x.name)}</strong><pre style="white-space:pre-wrap;max-height:160px;overflow:auto">${esc(x.chapters)}</pre></div>${btn('Export','export-story-'+i,'ghost')}</div>`).join('')}</div></section><section class="panel span12"><h3>Still on the roadmap</h3>${Object.entries(upcoming).map(([n,desc])=>`<p class="muted small"><strong>${esc(n)}</strong> — ${esc(desc)}</p>`).join('')}</section></div>`}
function playlistPicker(id){return `<select class="select" id="${id}"><option value="">Choose playlist…</option>${playlists.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select>`}
async function getItems(id){return paginate(`/playlists/${encodeURIComponent(id)}/items?limit=50`)}
function picked(id){let v=document.getElementById(id)?.value;if(!v)throw Error('Select the playlists first.');return v}
async function comparePlaylists(){let a=picked('compareA'),b=picked('compareB');let [aa,bb]=await Promise.all([getItems(a),getItems(b)]),setA=new Set(playlistUris(aa)),setB=new Set(playlistUris(bb));let common=[...setA].filter(x=>x&&setB.has(x));let onlyA=[...setA].filter(x=>x&&!setB.has(x));let onlyB=[...setB].filter(x=>x&&!setA.has(x));let names=new Map([...aa,...bb].map(x=>[normTrack(x).uri,normTrack(x).name]));document.querySelector('#compareResult').innerHTML=`<div class="note"><strong>${common.length} shared tracks</strong><p>${onlyA.length} unique to first · ${onlyB.length} unique to second</p><p class="muted small">Shared: ${common.slice(0,18).map(x=>esc(names.get(x)||x)).join(' · ')||'None'}</p></div>`}
let pendingMerge=null,pendingSort=null;
async function previewMerge(){let a=picked('mergeA'),b=picked('mergeB'),name=$('#mergeName').value.trim();if(!name)throw Error('Enter a name for your new playlist.');let [aa,bb]=await Promise.all([getItems(a),getItems(b)]);let uris=playlistUris([...aa,...bb]);if(uris.some(x=>!x))throw Error('Some tracks are unavailable/local. Merge cancelled to avoid losing items.');if($('#mergeUnique').checked)uris=uniquePlaylistUris(uris);pendingMerge={a,b,name,uris};$('#mergeResult').innerHTML=`<div class="note">Ready to create <strong>${uris.length}</strong> tracks in a new playlist called <strong>${esc(name)}</strong>. ${btn('Create merged playlist','commit-merge','primary')}</div>`}
async function commitMerge(){if(!pendingMerge||!me)throw Error('Preview a merge and connect Spotify first.');const {name,uris}=pendingMerge;if(!confirm(`Create \"${name}\" with ${uris.length} tracks?`))return;let created=await api('/me/playlists',{method:'POST',body:JSON.stringify({name,public:false,description:'Merged with SoundLab'})});for(let i=0;i<uris.length;i+=100)await api(`/playlists/${created.id}/items`,{method:'POST',body:JSON.stringify({uris:uris.slice(i,i+100)})});pendingMerge=null;await loadPlaylists();toast('Merged playlist created.')}
async function previewSort(){let id=picked('sortPlaylist'),p=playlists.find(x=>x.id===id);if(!me||p.owner?.id!==me.id)throw Error('You can only sort playlists you own.');let items=await getItems(id),uris=playlistUris(items);if(uris.some(x=>!x))throw Error('Sort disabled for unavailable or local tracks.');let mode=$('#sortMode').value;let sorted=[...items];if(mode==='reverse')sorted.reverse();else sorted.sort((a,b)=>{let x=normTrack(a),y=normTrack(b);let val=z=>mode==='artist'?z.artists?.[0]?.name:mode==='album'?z.album?.name:z.name;return String(val(x)||'').localeCompare(String(val(y)||''))});let desired=playlistUris(sorted);pendingSort={id,original:uris,desired,snapshot:p.snapshot_id};$('#sortResult').innerHTML=`<div class="note">Preview: ${sorted.slice(0,12).map(x=>esc(normTrack(x).name)).join(' → ')}${sorted.length>12?'…':''}<p class="muted small">Replaces the existing playlist order; added-at timestamps may change.</p>${btn('Confirm reorder','commit-sort','primary')}</div>`}
async function commitSort(){if(!pendingSort)throw Error('Preview a sort first.');const {id,original,desired,snapshot}=pendingSort;let current=await api(`/playlists/${id}`);if(snapshot&&snapshot!==current.snapshot_id)throw Error('The playlist changed since your preview. Reload and try again.');let now=playlistUris(await getItems(id));if(!sameUris(now,original))throw Error('The playlist changed since your preview.');if(!confirm(`Reorder ${desired.length} songs in the original playlist? SoundLab will save a backup first.`))return;saveBackupRecord({name:current.name,date:new Date().toISOString(),id,uris:original,reason:'before sort'});await replacePlaylist(id,desired);pendingSort=null;await loadPlaylists();toast('Playlist sorted; original order backed up.')}
async function replacePlaylist(id,uris){if(!uris.length)throw Error('Empty playlist replacement is disabled.');await api(`/playlists/${id}/items`,{method:'PUT',body:JSON.stringify({uris:uris.slice(0,100)})});for(let i=100;i<uris.length;i+=100)await api(`/playlists/${id}/items`,{method:'POST',body:JSON.stringify({uris:uris.slice(i,i+100)})});let actual=playlistUris(await getItems(id));if(!sameUris(actual,uris))throw Error('Spotify returned unexpected track order. Check the playlist and restore from Music Vault if needed.')}
function saveBackupRecord(b){let list=JSON.parse(localStorage.getItem('soundlab.backups.v1')||'[]');list.unshift(b);try{localStorage.setItem('soundlab.backups.v1',JSON.stringify(list.slice(0,30)))}catch{download('soundlab-emergency-backup.json',JSON.stringify(b,null,2));throw Error('Could not save a browser backup; exported an emergency JSON file. No changes were made.')}}
async function restoreBackup(i){let b=JSON.parse(localStorage.getItem('soundlab.backups.v1')||'[]')[i];if(!b)throw Error('Backup not found.');if(!me)throw Error('Connect Spotify first.');let p=await api(`/playlists/${b.id}`);if(p.owner?.id!==me.id)throw Error('You must own this playlist to restore it.');let now=playlistUris(await getItems(b.id));if(now.some(x=>!x)||b.uris.some(x=>!x))throw Error('Cannot safely restore unavailable/local items.');if(!confirm(`Restore ${b.uris.length} entries in \"${p.name}\"? This REPLACES its current songs. A snapshot of the current songs will be saved first.`))return;saveBackupRecord({name:p.name,date:new Date().toISOString(),id:b.id,uris:now,reason:'before restoration'});await replacePlaylist(b.id,b.uris);await loadPlaylists();toast('Backup restored. Check your Spotify playlist.')}
async function importBackup(){let f=$('#backupFile').files?.[0];if(!f)throw Error('Choose a backup JSON file.');let b=JSON.parse(await f.text());if(!b||typeof b.id!=='string'||!Array.isArray(b.uris)||b.uris.some(x=>!/^spotify:(track|episode):/.test(x)))throw Error('Not a valid SoundLab playlist backup.');saveBackupRecord({...b,name:String(b.name||'Imported backup'),date:new Date().toISOString()});render();toast('Backup imported into Music Vault.')}
async function globalSearch(){let term=$('#globalSearch').value.trim().toLowerCase();if(term.length<2)throw Error('Enter at least two letters.');let el=$('#globalResult');el.textContent='Searching playlists…';let found=[],errors=0;for(const p of playlists){try{let items=await getItems(p.id);let hits=items.filter(x=>{let t=normTrack(x);return `${t.name||''} ${(t.artists||[]).map(a=>a.name).join(' ')}`.toLowerCase().includes(term)});if(hits.length)found.push({name:p.name,hits})}catch{errors++}}el.innerHTML=`<div class="note">${found.reduce((s,x)=>s+x.hits.length,0)} matches in ${found.length} playlists. ${errors?'Could not scan '+errors+' playlists.':''}</div>`+found.map(x=>`<p><strong>${esc(x.name)}</strong>: ${x.hits.slice(0,12).map(y=>esc(normTrack(y).name)).join(', ')}</p>`).join('')}
function timezoneOptions(){return [...new Set([timezone(),...TIMEZONES])].map(z=>`<option value="${esc(z)}" ${timezone()===z?'selected':''}>${esc(z)}</option>`).join('')}
function settingsPage(){return `${title('Settings & Data','Connect Spotify to manage playlists and control your locally imported music history.')}<div class="layout"><section class="panel span6"><h3>Spotify authentication</h3><p class="muted small">Create your own Spotify Developer application and paste its Client ID. Do not paste a Client Secret.</p><label class="field">Spotify Client ID<input id="clientId" class="input" value="${esc(settings.clientId||'')}" placeholder="Spotify application Client ID"></label><p class="small muted">Register this exact redirect URI in your Spotify Developer Dashboard:</p><div class="item"><code>${esc(redirectUri())}</code>${btn('Copy','copy-redirect','ghost')}</div><div class="row" style="margin-top:15px">${btn('Save Client ID','save-client','primary')}${me?btn('Disconnect','disconnect','ghost'):btn('Connect Spotify','connect','secondary')}</div><p class="small muted">Uses Spotify Authorization Code with PKCE. No client secret is stored. Tokens remain in session storage, not uploaded to SoundLab.</p></section><section class="panel span6"><h3>Listening history and privacy</h3><div class="note warning"><strong>Why isn't automatic listening tracking offered?</strong><p>Spotify's developer policy restricts creating new listening metrics or user profiles from Spotify Platform API data. SoundLab therefore does not collect recently played tracks, count streams from Spotify's API, or run background listening synchronisation. Listening Analytics uses only files you choose to import. <a href="https://developer.spotify.com/policy" target="_blank" rel="noopener noreferrer">Spotify Developer Policy ↗</a></p><p>Spotify playlist management is separate: your playlists load when you connect and when you choose Refresh playlists. This is not listening-history tracking.</p></div><div class="row" style="margin-top:14px">${btn('Refresh playlists now','refresh','secondary')}${btn('Delete imported history','delete-history','danger')}${btn('Delete journal','delete-journal','ghost')}</div><div class="divider"></div><h3>Your location & display timezone</h3><p class="muted small">Choose where you live, or the timezone you want your music history to reflect. SoundLab stores only the timezone name, not your street address or GPS location. This changes daily, weekly, monthly and hourly groupings without changing imported timestamps.</p><label class="field">Timezone<select id="settingsTimezone" class="select">${timezoneOptions()}</select></label><div class="divider"></div><h3>Historical data</h3><p class="muted">Request your Extended Streaming History from Spotify, then upload the ZIP or JSON files to update your listening statistics. Your imported history stays in IndexedDB in this browser. Clearing browser storage also removes it; it is not synced between devices.</p><div class="row">${btn('Open history importer','goto-history','ghost')}<a href="https://www.spotify.com/account/privacy/" target="_blank" rel="noopener noreferrer">Request Spotify data ↗</a></div></section></div>`}
function redirectUri(){return location.origin+location.pathname}
function randomString(len=64){const b=crypto.getRandomValues(new Uint8Array(len));return [...b].map(x=>'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~'[x%66]).join('')}
const base64url=bytes=>btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
async function connect(){if(!settings.clientId){current='settings';render();toast('First save a Spotify Client ID in Settings.',true);return}const verifier=randomString(),state=randomString(30);sessionStorage.setItem('sl.verifier',verifier);sessionStorage.setItem('sl.state',state);const challenge=base64url(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))));const u=new URL('https://accounts.spotify.com/authorize');u.search=new URLSearchParams({response_type:'code',client_id:settings.clientId,scope:'playlist-read-private playlist-read-collaborative playlist-modify-public playlist-modify-private user-read-private',redirect_uri:redirectUri(),code_challenge_method:'S256',code_challenge:challenge,state});location.assign(u.href)}
async function exchange(params){let code=params.get('code');if(!code)return;if(params.get('state')!==sessionStorage.getItem('sl.state'))throw Error('Spotify sign-in state did not match. Please try again.');const body=new URLSearchParams({grant_type:'authorization_code',code,redirect_uri:redirectUri(),client_id:settings.clientId,code_verifier:sessionStorage.getItem('sl.verifier')});const res=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});let obj=await res.json();if(!res.ok)throw Error(obj.error_description||'Sign-in failed');saveToken(obj);history.replaceState({},'',redirectUri());sessionStorage.removeItem('sl.verifier');sessionStorage.removeItem('sl.state')}
function saveToken(obj){token=obj.access_token;expires=Date.now()+obj.expires_in*1000-60000;sessionStorage.setItem('sl.auth',JSON.stringify({token,expires,refresh:obj.refresh_token||getAuth()?.refresh}))}
function getAuth(){try{return JSON.parse(sessionStorage.getItem('sl.auth')||'null')}catch{return null}}
async function validToken(){let a=getAuth();if(!a)throw Error('Please connect Spotify first.');if(Date.now()<a.expires&&a.token)return a.token;if(!a.refresh)throw Error('Spotify session expired. Please connect again.');let body=new URLSearchParams({grant_type:'refresh_token',refresh_token:a.refresh,client_id:settings.clientId});let res=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});let d=await res.json();if(!res.ok)throw Error('Could not refresh Spotify login. Please reconnect.');saveToken(d);return token}
async function api(path,opts={}){let t=await validToken();let res=await fetch(path.startsWith('https:')?path:'https://api.spotify.com/v1'+path,{...opts,headers:{Authorization:`Bearer ${t}`,...(opts.body?{'Content-Type':'application/json'}:{}),...opts.headers}});if(!res.ok){let err;try{err=await res.json()}catch{};throw Error(`Spotify ${res.status}: ${err?.error?.message||res.statusText}${res.status===429?' (rate limited; try later)':''}`)}return res.status===204?{}:res.json()}
async function paginate(path,onProgress){let list=[],next=path;let count=0;while(next&&count++<120){let page=await api(next);list.push(...(page.items||[]));if(onProgress)onProgress(list.length,Number(page.total)||0);next=page.next}return list}
async function loadPlaylists(){if(!getAuth()){toast('Connect Spotify to load playlists.',true);return}playlists=await paginate('/me/playlists?limit=50');render();toast(`Loaded ${playlists.length} Spotify playlists.`)}
async function selectPlaylist(id){
  const choice=playlists.find(p=>p.id===id);
  if(!choice)throw Error('Playlist not found.');
  selected=choice;tracks=[];duplicateGroups=[];
  const currentScan={active:true,loaded:0,total:choice.items?.total??choice.tracks?.total??0,percent:0};
  scanProgress=currentScan;render();
  try{
    const items=await paginate(`/playlists/${encodeURIComponent(id)}/items?limit=50`,(count,total)=>{
      if(scanProgress!==currentScan)return;
      currentScan.loaded=count;
      currentScan.total=Math.max(total||0,count);
      currentScan.percent=total?Math.min(99,Math.round(count/total*100)):0;
      const label=$('#scanProgressText'),bar=$('#scanProgressBar'),fill=$('#scanProgressFill');
      if(label)label.textContent=`${count.toLocaleString()} of ${currentScan.total?currentScan.total.toLocaleString():'…'} tracks checked`;
      if(bar)bar.setAttribute('aria-valuenow',String(currentScan.percent));
      if(fill)fill.style.width=currentScan.percent+'%';
    });
    if(scanProgress!==currentScan)return;
    tracks=items;duplicateGroups=scan(items);
    scanProgress=null;render();toast(`Scanned ${items.length} tracks. ${duplicateGroups.reduce((a,g)=>a+g.count-1,0)} extra copies found.`);
  }catch(err){if(scanProgress===currentScan){scanProgress=null;render()}throw err}
}
function download(name,data,mime='application/json'){let blob=new Blob([data],{type:mime}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function backupPlaylist(){if(!selected)return;const list=JSON.parse(localStorage.getItem('soundlab.backups.v1')||'[]');const record={name:selected.name,date:new Date().toISOString(),id:selected.id,uris:tracks.map(t=>normTrack(t).uri).filter(Boolean)};list.unshift(record);try{localStorage.setItem('soundlab.backups.v1',JSON.stringify(list.slice(0,30)))}catch{download(`soundlab-${selected.id}-backup.json`,JSON.stringify(record,null,2));toast('Browser storage full. Downloaded backup instead.');return}render();toast('Local backup saved. For safety, download it from Music Vault.')}
// Spotify's DELETE playlist-items endpoint removes every occurrence of a URI,
// even when a `positions` property is supplied. Never use it for direct
// per-occurrence deletion. Remove every occurrence and add a single copy back
// at the original (adjusted) position, checking the result after each edit.
const playlistUris=items=>items.map(x=>normTrack(x).uri||null);
const sameUris=(a,b)=>a.length===b.length&&a.every((uri,i)=>uri===b[i]);
const uniquePlaylistUris=uris=>{const seen=new Set();return uris.filter(uri=>!seen.has(uri)&&!!seen.add(uri));};
async function removeDuplicatesInPlace(){
  if(!selected||!me||selected.owner?.id!==me.id)throw Error('You must own this playlist to remove duplicates.');
  const playlistId=selected.id;
  const endpoint=`/playlists/${encodeURIComponent(playlistId)}`;
  const originalSnapshot=selected.snapshot_id;
  // Refuse to mutate a playlist that was edited after the user opened it.
  const fresh=await api(endpoint);
  if(originalSnapshot&&fresh.snapshot_id!==originalSnapshot){
    throw Error('This playlist changed since it was loaded. Please select it again before removing duplicates.');
  }
  const latest=await paginate(`${endpoint}/items?limit=50`);
  const originals=playlistUris(latest);
  if(originals.some(uri=>!uri))throw Error('This playlist includes unavailable or local tracks. Cleanup has been disabled to avoid accidentally losing those items.');
  const wanted=uniquePlaylistUris(originals);
  const removeCount=originals.length-wanted.length;
  if(!removeCount){toast('No exact duplicates to remove.');return}
  const duplicateUris=new Set(originals.filter((uri,i)=>originals.indexOf(uri)!==i));
  const groups=wanted.filter(uri=>duplicateUris.has(uri));
  if(!confirm(`Clean ${removeCount} extra occurrence${removeCount===1?'':'s'} from "${selected.name}"?\n\nSoundLab will keep one copy of each song in the same order. Spotify deletes every occurrence of a repeated song, so SoundLab must re-add one copy. This can reset that song's Date Added.\n\nThe original playlist will be backed up before editing. No new playlist will be made.`))return;
  // Persist full original order as a recoverable safety record before mutation.
  const backups=JSON.parse(localStorage.getItem('soundlab.backups.v1')||'[]');
  const backup={name:selected.name,date:new Date().toISOString(),id:playlistId,
    uris:originals,reason:'before duplicate removal'};
  try{
    localStorage.setItem('soundlab.backups.v1',JSON.stringify([backup,...backups].slice(0,30)));
  }catch(e){throw Error('Could not save the safety backup. No songs were removed. Free up browser storage and try again.')}
  let working=originals.slice(), expectedSnapshot=fresh.snapshot_id;
  try{
    for(const uri of groups){
      // Re-check the current playlist before EACH destructive API request.
      const live=await api(endpoint);
      const currentUris=playlistUris(await paginate(`${endpoint}/items?limit=50`));
      if(live.snapshot_id!==expectedSnapshot||!sameUris(currentUris,working)){
        throw Error('The playlist was changed elsewhere. Cleanup stopped to prevent unexpected edits.');
      }
      const first=working.indexOf(uri);
      // After removing every instance, these are the entries before the
      // original first occurrence that still remain, hence the insert index.
      const insertAt=working.slice(0,first).filter(x=>x!==uri).length;
      const without=working.filter(x=>x!==uri);
      const deleteResult=await api(`${endpoint}/items`,{
        method:'DELETE',body:JSON.stringify({items:[{uri}],snapshot_id:expectedSnapshot})
      });
      expectedSnapshot=deleteResult.snapshot_id;
      // Check removal exactly before putting the kept occurrence back.
      const afterDelete=playlistUris(await paginate(`${endpoint}/items?limit=50`));
      if(!sameUris(afterDelete,without)){
        throw Error('Spotify returned unexpected playlist contents after removal. Cleanup stopped.');
      }
      const addResult=await api(`${endpoint}/items`,{
        method:'POST',body:JSON.stringify({uris:[uri],position:insertAt})
      });
      expectedSnapshot=addResult.snapshot_id;
      const restored=[...without.slice(0,insertAt),uri,...without.slice(insertAt)];
      const afterAdd=playlistUris(await paginate(`${endpoint}/items?limit=50`));
      if(!sameUris(afterAdd,restored)){
        throw Error('Spotify returned unexpected playlist contents after re-adding a song. Cleanup stopped.');
      }
      working=restored;
    }
    if(!sameUris(working,wanted))throw Error('Final playlist did not match the expected track order.');
  }catch(e){
    throw Error(`Cleanup stopped: ${e.message} A backup of the original song order is in Music Vault. Reopen the playlist to check it before trying again.`);
  }
  await loadPlaylists();
  await selectPlaylist(playlistId);
  toast(`Removed ${removeCount} extra occurrences. One copy of each song remains in the original playlist.`);
}
function db(){return new Promise((resolve,reject)=>{let req=indexedDB.open('soundlab-history-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('plays',{keyPath:'key'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function readHistory(){const database=await db();return new Promise((resolve,reject)=>{let t=database.transaction('plays','readonly'),r=t.objectStore('plays').getAll();r.onsuccess=()=>{database.close();resolve(r.result)};r.onerror=()=>reject(r.error)})}
const hash=s=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)};
function normalise(r){let ts=r.ts||r.endTime||r.end_time,ms=Number(r.ms_played??r.msPlayed??0),track=r.master_metadata_track_name||r.trackName||r.track_name,artist=r.master_metadata_album_artist_name||r.artistName||r.artist_name||'',album=r.master_metadata_album_album_name||r.albumName||'',uri=r.spotify_track_uri||r.spotifyTrackUri||'';if(!ts||!track||!Number.isFinite(ms)||ms<0||Number.isNaN(Date.parse(ts)))return null;let canonical=new Date(ts).toISOString();let fingerprint=[canonical,ms,uri||`${track}|${artist}|${album}`].join('|');return {key:hash(fingerprint)+'|'+fingerprint,ts:canonical,ms,track,artist,album,uri}}
async function importHistory(){let files=$('#historyFiles').files;if(!files.length)throw Error('Choose a ZIP or JSON file first.');$('#importStatus').textContent='Reading files locally…';let records=[];for(const f of files){if(f.name.toLowerCase().endsWith('.zip')){let zip=await JSZip.loadAsync(f);for(const entry of Object.values(zip.files)){if(entry.dir||!entry.name.toLowerCase().endsWith('.json')||!/(endsong|streaminghistory|audio)/i.test(entry.name))continue;let obj=JSON.parse(await entry.async('string'));if(Array.isArray(obj))records.push(...obj)}}else if(f.name.toLowerCase().endsWith('.json')){let obj=JSON.parse(await f.text());if(Array.isArray(obj))records.push(...obj)}}if(!records.length)throw Error('No recognised listening records found. Select Spotify StreamingHistory or endsong JSON files.');let normalized=records.map(normalise).filter(Boolean),database=await db(),total=0;for(let i=0;i<normalized.length;i+=1200){let slice=normalized.slice(i,i+1200);await new Promise((resolve,reject)=>{let tx=database.transaction('plays','readwrite');let store=tx.objectStore('plays');for(let x of slice)store.put(x);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});total+=slice.length;$('#importStatus').textContent=`Processed ${total.toLocaleString()} / ${normalized.length.toLocaleString()} valid records…`;await new Promise(r=>setTimeout(r,0))}database.close();plays=await readHistory();render();toast(`Import complete: ${normalized.length.toLocaleString()} valid records processed; ${plays.length.toLocaleString()} unique local records.`)}
async function wipeHistory(){if(!confirm('Permanently delete imported listening records from THIS browser?'))return;const database=await db();await new Promise((resolve,reject)=>{let t=database.transaction('plays','readwrite');t.objectStore('plays').clear();t.oncomplete=resolve;t.onerror=()=>reject(t.error)});database.close();plays=[];render();toast('Imported history deleted from this browser.')}
let found=[];
async function findPasted(){if(!me)throw Error('Connect your Spotify account first.');let lines=$('#pasteText').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,100);if(!lines.length)throw Error('Paste at least one song.');found=[];let area=$('#pasteResults');area.textContent=`Searching for ${lines.length} tracks…`;for(let [idx,line] of lines.entries()){let pieces=line.split(/\s+[-–—]\s+/),title=pieces[0],artist=pieces.slice(1).join(' ');let query=`track:${title}${artist?` artist:${artist}`:''}`;let r=await api('/search?'+new URLSearchParams({q:query,type:'track',limit:'3'}));let match=r.tracks?.items?.[0]||null;found.push({line,match,include:!!match});area.textContent=`Searched ${idx+1}/${lines.length} songs…`}drawPasted()}
function drawPasted(){const area=$('#pasteResults');if(!area)return;area.innerHTML=`<div class="list">${found.map((x,i)=>`<label class="item"><span><input type="checkbox" data-paste-check="${i}" ${x.include?'checked':''} ${x.match?'':'disabled'}> <strong>${esc(x.line)}</strong><div class="itemSub">${x.match?`Matched: ${esc(x.match.name)} · ${esc(x.match.artists?.map(a=>a.name).join(', '))}`:'No Spotify match found'}</div></span></label>`).join('')}</div><div style="margin-top:14px">${btn('Create playlist from checked matches','create-pasted','primary')}</div>`}
async function createPasted(){let name=$('#pasteName')?.value.trim()||'My SoundLab Mix',uris=found.filter(x=>x.include&&x.match).map(x=>x.match.uri);if(!uris.length)throw Error('Select at least one matched song.');if(!confirm(`Create a Spotify playlist called "${name}" with ${uris.length} tracks?`))return;let p=await api('/me/playlists',{method:'POST',body:JSON.stringify({name,public:false,description:'Created with SoundLab Playlist Paster'})});for(let i=0;i<uris.length;i+=100)await api(`/playlists/${p.id}/items`,{method:'POST',body:JSON.stringify({uris:uris.slice(i,i+100)})});toast('Spotify playlist created: '+name);loadPlaylists()}
async function action(id){if(id==='load-artwork')return loadAnalyticsArtwork();if(id==='export-recap')return exportRecap();if(id==='search-albums')return searchAlbums();if(id==='clear-album')return clearAlbumSelection();if(id==='connect')return connect();if(id==='refresh')return loadPlaylists();if(id==='goto-playlists'){current='playlists';render();return}if(id==='goto-history'||id==='choose-import'){settings.onboarding='import';saveSettings();current=id==='choose-import'?'dashboard':'history';render();return}if(id==='choose-now'){settings.onboarding='now';saveSettings();render();return}if(id==='save-client'){let val=$('#clientId').value.trim();if(!/^[a-zA-Z0-9]{20,64}$/.test(val))throw Error('Enter a valid Spotify Client ID.');settings.clientId=val;saveSettings();toast('Client ID saved in this browser.');return}if(id==='copy-redirect'){await navigator.clipboard.writeText(redirectUri());toast('Redirect URI copied.');return}if(id==='disconnect'){sessionStorage.removeItem('sl.auth');token=null;me=null;playlists=[];selected=null;render();return}if(id==='backup')return backupPlaylist();if(id==='clean')return removeDuplicatesInPlace();if(id==='import-history')return importHistory();if(id==='export-history'){if(!plays.length)throw Error('No imported history available.');download('soundlab-history-export.json',JSON.stringify(plays,null,2));return}if(id==='delete-history')return wipeHistory();if(id==='delete-journal'){if(!confirm('Delete your entire album journal from this browser?'))return;journal.splice(0);localStorage.setItem(JOURNAL,'[]');render();return}if(id.startsWith('download-backup-')){let index=Number(id.split('-').at(-1)),b=JSON.parse(localStorage.getItem('soundlab.backups.v1')||'[]')[index];if(b)download(`soundlab-playlist-${b.id}.json`,JSON.stringify(b,null,2));return}if(id==='compare')return comparePlaylists();if(id==='preview-merge')return previewMerge();if(id==='commit-merge')return commitMerge();if(id==='preview-sort')return previewSort();if(id==='commit-sort')return commitSort();if(id==='global-search')return globalSearch();if(id==='import-backup')return importBackup();if(id==='export-journal'){download('soundlab-album-journal.json',JSON.stringify(journal,null,2));return}if(id.startsWith('restore-backup-'))return restoreBackup(Number(id.split('-').at(-1)));if(id.startsWith('export-story-')){let stories=JSON.parse(localStorage.getItem('soundlab.architect.v1')||'[]');let story=stories[Number(id.split('-').at(-1))];if(story)download('soundlab-playlist-story.txt',story.name+'\n\n'+story.chapters,'text/plain');return}if(id==='find-pasted')return findPasted();if(id==='create-pasted')return createPasted()}
document.addEventListener('click',async e=>{let period=e.target.closest('[data-period]');if(period){historyPeriod=period.dataset.period;render();return}let pageButton=e.target.closest('[data-page]');if(pageButton){current=pageButton.dataset.page;render();return}let pl=e.target.closest('[data-playlist]');if(pl){try{await selectPlaylist(pl.dataset.playlist)}catch(err){toast(err.message,true)}return}let b=e.target.closest('[data-action]');if(b){b.disabled=true;try{await action(b.dataset.action)}catch(err){toast(err.message||String(err),true)}finally{if(b.isConnected)b.disabled=false}return}let pick=e.target.closest('[data-pick-album]');if(pick){pickAlbum(Number(pick.dataset.pickAlbum));return}let del=e.target.closest('[data-delete-album]');if(del){journal.splice(Number(del.dataset.deleteAlbum),1);localStorage.setItem(JOURNAL,JSON.stringify(journal));render()}});
document.addEventListener('input',e=>{if(e.target.id==='playlistSearch')$('#playlistList').innerHTML=playlistCards(e.target.value)});
document.addEventListener('keydown',e=>{if(e.target.id==='albumSearch'&&e.key==='Enter'){e.preventDefault();searchAlbums().catch(err=>toast(err.message,true))}});
document.addEventListener('change',e=>{if(['settingsTimezone','historyTimezone'].includes(e.target.id)){settings.timezone=e.target.value;saveSettings();historyAnchor=localToday();artworkLastQuery='';render();toast('Timezone updated to '+timezone());return}if(['historyAnchor','historyFrom','historyTo'].includes(e.target.id)){if(e.target.id==='historyAnchor')historyAnchor=e.target.value;if(e.target.id==='historyFrom')historyFrom=e.target.value;if(e.target.id==='historyTo')historyTo=e.target.value;render();return}if(e.target.matches('[data-paste-check]'))found[Number(e.target.dataset.pasteCheck)].include=e.target.checked});
document.addEventListener('submit',e=>{if(e.target.id==='architectForm'){e.preventDefault();let f=new FormData(e.target),a=JSON.parse(localStorage.getItem('soundlab.architect.v1')||'[]');a.unshift({name:String(f.get('name')).trim(),chapters:String(f.get('chapters')).trim()});localStorage.setItem('soundlab.architect.v1',JSON.stringify(a));render();toast('Playlist story saved.');return}if(e.target.id!=='albumForm')return;e.preventDefault();let f=new FormData(e.target);journal.unshift({name:String(f.get('name')).trim(),artist:String(f.get('artist')).trim(),rating:String(f.get('rating')),status:String(f.get('status')),notes:String(f.get('notes')).trim(),spotifyId:String(f.get('spotifyId')||''),spotifyUrl:String(f.get('spotifyUrl')||''),image:String(f.get('image')||''),releaseDate:String(f.get('releaseDate')||''),totalTracks:Number(f.get('totalTracks')||0)});localStorage.setItem(JOURNAL,JSON.stringify(journal));render();toast('Album added to your journal.')});
async function start(){render();try{let q=new URLSearchParams(location.search);if(q.has('error')){history.replaceState({},'',redirectUri());throw Error('Spotify authorisation was cancelled or denied.')}if(q.has('code'))await exchange(q);const auth=getAuth();if(auth){me=await api('/me');playlists=await paginate('/me/playlists?limit=50')}plays=await readHistory();render();if(q.has('code'))toast('Spotify connected successfully.')}catch(e){render();toast(e.message,true)}}start();
